def optimize_snowsprite(override):
    override('Actors/Snow.cs', [('var subtex = Assets.Subtextures["circle"];', 'var subtex = Assets.Subtextures["circle"];\n        // Texture and default flags stay constant throughout this collection.\n        Sprite flakeSprite = new() { Subtexture = subtex };'), ('var color = Color.White * alpha;', 'var color = Color.White * alpha;\n            flakeSprite.Color = color;'), ('populate.Add(new Sprite {\n                    Subtexture = subtex,\n                    A = point + billboardLeft + billboardUp,\n                    B = point - billboardLeft + billboardUp,\n                    C = point - billboardLeft - billboardUp,\n                    D = point + billboardLeft - billboardUp,\n                    Color = color\n                });', 'flakeSprite.A = point + billboardLeft + billboardUp;\n                flakeSprite.B = point - billboardLeft + billboardUp;\n                flakeSprite.C = point - billboardLeft - billboardUp;\n                flakeSprite.D = point + billboardLeft - billboardUp;\n                populate.Add(flakeSprite);')])
